import json

with open('/home/agent/.gemini/antigravity/brain/49626454-f72c-4658-8655-6a45650f1439/scratch/detected_kicks_v2.json') as f:
    kicks = json.load(f)

# Group kicks by phase
kicks_by_phase = {}
for k in kicks:
    p_id = k['phase']
    if p_id not in kicks_by_phase:
        kicks_by_phase[p_id] = []
    kicks_by_phase[p_id].append(k)

chains = []

# Phase goals definition
# Phase 7 ends with a white goal. Phase 15 ends with a white goal.
phase_goals = {
    7: 'white',
    15: 'white'
}

for p_id in sorted(kicks_by_phase.keys()):
    p_kicks = kicks_by_phase[p_id]

    # Group into raw chains (consecutive kicks by same team)
    raw_chains = []
    current_chain = []
    for k in p_kicks:
        if len(current_chain) == 0:
            current_chain.append(k)
        else:
            if k['team'] == current_chain[-1]['team']:
                current_chain.append(k)
            else:
                raw_chains.append(current_chain)
                current_chain = [k]
    if len(current_chain) > 0:
        raw_chains.append(current_chain)

    # Process raw chains
    for idx, rc in enumerate(raw_chains):
        team = rc[0]['team']
        half = rc[0]['half']
        kick_count = len(rc)

        # zone_path
        zones = [k['zone'] for k in rc]
        collapsed_zones = []
        for z in zones:
            if len(collapsed_zones) == 0 or z != collapsed_zones[-1]:
                collapsed_zones.append(z)

        # terminal
        if idx < len(raw_chains) - 1:
            terminal = 'turnover'
        else:
            # last chain of the phase
            goal_team = phase_goals.get(p_id, None)
            if goal_team == team:
                terminal = 'goal'
            else:
                terminal = 'stoppage'

        # Only report qualifying chains (>= 2 kicks)
        qualifying = (kick_count >= 2)

        chains.append({
            \"phase\": p_id,
            \"half\": half,
            \"team\": team,
            \"kick_count\": kick_count,
            \"zone_path\": collapsed_zones,
            \"terminal\": terminal,
            \"qualifying\": qualifying,
            \"frames\": [k['frame'] for k in rc]
        })

print('=== ALL DETECTED CHAINS ===')
qual_count = 0
for idx, c in enumerate(chains):
    if c['qualifying']:
        qual_count += 1
        print(f\"Chain {qual_count}: Half={c['half']}, Team={c['team']}, Kicks={c['kick_count']}, Zones={c['zone_path']}, Terminal={c['terminal']}, Phase={c['phase']}, Frames={c['frames']}\")
    else:
        print(f\"(Unqualified) Single-kick by {c['team']} at F{c['frames'][0]} in Phase {c['phase']}\")
